package com.medinasystems.pos.customer.domain;

import java.util.Objects;
import java.util.stream.Collectors;
import java.util.stream.Stream;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Table;

import com.medinasystems.pos.shared.AuditableEntity;

/**
 * A customer (cliente). The price list is kept as an id: the customer module never holds pricing entities. The
 * display name is a column generated by the database (V16); the getter computes the same value for the object in memory,
 * so a customer that was just saved shows it without a reload.
 */
@Entity
@Table(name = "customer")
public class Customer extends AuditableEntity {

    @Column(name = "external_code", length = 50)
    private String externalCode;

    @Enumerated(EnumType.STRING)
    @Column(name = "customer_type", nullable = false, length = 10)
    private CustomerType customerType;

    @Enumerated(EnumType.STRING)
    @Column(name = "document_type", nullable = false, length = 10)
    private DocumentType documentType;

    @Column(name = "document_number", length = 20)
    private String documentNumber;

    @Column(name = "first_name", length = 60)
    private String firstName;

    @Column(name = "middle_name", length = 60)
    private String middleName;

    @Column(name = "last_name", length = 60)
    private String lastName;

    @Column(name = "second_last_name", length = 60)
    private String secondLastName;

    @Column(name = "business_name", length = 200)
    private String businessName;

    /** Generated by PostgreSQL: read for searching and sorting, never written. */
    @Column(name = "display_name", length = 250, insertable = false, updatable = false)
    private String displayName;

    @Column(length = 20)
    private String phone;

    @Column(length = 150)
    private String email;

    @Column(length = 300)
    private String address;

    @Column(name = "price_list_id")
    private Long priceListId;

    @Column(nullable = false)
    private boolean active = true;

    protected Customer() {
    }

    public Customer(CustomerDetails details) {
        apply(details);
    }

    /** Changes every editable field. The service checks the uniqueness rules before calling. */
    public void update(CustomerDetails details) {
        apply(details);
    }

    /** Customers are deactivated, never deleted: old documents still point to them. */
    public void deactivate() {
        this.active = false;
    }

    private void apply(CustomerDetails details) {
        this.externalCode = details.externalCode();
        this.customerType = details.customerType();
        this.documentType = details.documentType();
        this.documentNumber = details.documentNumber();
        this.firstName = details.firstName();
        this.middleName = details.middleName();
        this.lastName = details.lastName();
        this.secondLastName = details.secondLastName();
        this.businessName = details.businessName();
        this.phone = details.phone();
        this.email = details.email();
        this.address = details.address();
        this.priceListId = details.priceListId();
        this.active = details.active();
    }

    /** The business name for a company; otherwise the names that are present, separated by spaces. */
    public String getDisplayName() {
        if (customerType == CustomerType.COMPANY) {
            return businessName;
        }
        return Stream.of(firstName, middleName, lastName, secondLastName)
                .filter(Objects::nonNull)
                .collect(Collectors.joining(" "));
    }

    public String getExternalCode() {
        return externalCode;
    }

    public CustomerType getCustomerType() {
        return customerType;
    }

    public DocumentType getDocumentType() {
        return documentType;
    }

    public String getDocumentNumber() {
        return documentNumber;
    }

    public String getFirstName() {
        return firstName;
    }

    public String getMiddleName() {
        return middleName;
    }

    public String getLastName() {
        return lastName;
    }

    public String getSecondLastName() {
        return secondLastName;
    }

    public String getBusinessName() {
        return businessName;
    }

    public String getPhone() {
        return phone;
    }

    public String getEmail() {
        return email;
    }

    public String getAddress() {
        return address;
    }

    public Long getPriceListId() {
        return priceListId;
    }

    public boolean isActive() {
        return active;
    }
}
